const A=document.querySelector('#app');
const TEAM_COLORS={ARI:'#97233F',ATL:'#A71930',BAL:'#241773',BUF:'#00338D',CAR:'#0085CA',CHI:'#0B162A',CIN:'#FB4F14',CLE:'#311D00',DAL:'#003594',DEN:'#FB4F14',DET:'#0076B6',GB:'#203731',HOU:'#03202F',IND:'#002C5F',JAX:'#006778',KC:'#E31837',LV:'#000',LAC:'#0080C6',LA:'#003594',MIA:'#008E97',MIN:'#4F2683',NE:'#002244',NO:'#D3BC8D',NYG:'#0B2265',NYJ:'#125740',PHI:'#004C54',PIT:'#FFB612',SF:'#AA0000',SEA:'#002244',TB:'#D50A0A',TEN:'#0C2340',WAS:'#5A1414'};
const ALIGN={'AFC East':['BUF','MIA','NE','NYJ'],'AFC North':['BAL','CIN','CLE','PIT'],'AFC South':['HOU','IND','JAX','TEN'],'AFC West':['DEN','KC','LV','LAC'],'NFC East':['DAL','NYG','PHI','WAS'],'NFC North':['CHI','DET','GB','MIN'],'NFC South':['ATL','CAR','NO','TB'],'NFC West':['ARI','LA','SF','SEA']};
const API_INFLIGHT=new Map();
let S={online:navigator.onLine,lastFetch:null,route:'home',teams:[],league:null,players:[],games:[],game:null,team:'SF',compareTeam:'KC',health:null,density:localStorage.getItem('atlas-density')||'comfort',pins:JSON.parse(localStorage.getItem('atlas-pins')||'[]')};
const normAb=ab=>({LAR:'LA',WSH:'WAS'}[String(ab||'').toUpperCase()]||String(ab||'').toUpperCase());
const esc=s=>String(s??'—').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const api=async(u,opt={})=>{if(API_INFLIGHT.has(u)&&!opt.force)return API_INFLIGHT.get(u);let job=(async()=>{let tries=opt.tries??2,last;for(let n=0;n<=tries;n++){let c=new AbortController(),to=setTimeout(()=>c.abort(),opt.timeout||9000);try{let r=await fetch(u,{signal:c.signal,cache:'no-store'});clearTimeout(to);if(!r.ok)throw Error('HTTP '+r.status);S.online=true;S.lastFetch=Date.now();return await r.json()}catch(e){clearTimeout(to);last=e;if(n<tries)await sleep(250*(n+1))}}S.online=false;throw last})();API_INFLIGHT.set(u,job);try{return await job}finally{API_INFLIGHT.delete(u)}};
function gameCounts(gs=[]){let live=0,final=0,pre=0;gs.forEach(g=>{let st=String(g.state||'').toLowerCase();if(st==='in')live++;else if(g.completed||st==='post'||String(g.status||'').toLowerCase().startsWith('final'))final++;else pre++});return {live,final,pre,total:gs.length}}
function liveRibbon(){let c=gameCounts(S.games),age=S.lastFetch?Math.max(0,Math.round((Date.now()-S.lastFetch)/1000)):null;return `<div class="liveRibbon" id="liveRibbon" data-state="${S.online===false?'offline':'online'}"><i class="livePulse"></i><b>${c.live?c.live+' LIVE GAME'+(c.live===1?'':'S'):'ATLAS GAME DAY'}</b><span>${c.final} FINAL · ${c.pre} UPCOMING</span><span class="push" id="feedAge">${S.online===false?'CONNECTION LOST':age==null?'SYNCING…':age+'s SINCE SYNC'}</span><button id="manualRefresh" title="Refresh current game-day data">↻ REFRESH</button></div>`}
function gameDayBar(gs=[]){let c=gameCounts(gs);return `<div class="gameDayBar"><div class="hot"><span>LIVE NOW</span><b>${c.live}</b></div><div><span>UPCOMING</span><b>${c.pre}</b></div><div class="final"><span>FINAL</span><b>${c.final}</b></div><div><span>FEED</span><b>${S.online===false?'RECONNECTING':'SMART POLL'}</b></div></div>`}
function wireLiveRibbon(){document.querySelector('#manualRefresh')?.addEventListener('click',async e=>{let b=e.currentTarget;b.innerHTML='<i class="refreshSpin">↻</i> SYNC';await refreshGameDay(true);b.textContent='↻ REFRESH'});clearInterval(window._atlasAge);window._atlasAge=setInterval(()=>{let e=document.querySelector('#feedAge');if(!e)return;let age=S.lastFetch?Math.round((Date.now()-S.lastFetch)/1000):0;e.textContent=S.online===false?'RECONNECTING':age>45?'STALE · '+age+'s':'LIVE · '+age+'s';e.dataset.liveAge=age>45?'stale':'fresh'},1000)}
async function refreshGameDay(renderAfter=false){if(document.hidden)return;try{let d=await api('/api/week?season=2026&type=2',{tries:1,timeout:7000});S.games=d.games||[];if(S.game){let fresh=S.games.find(x=>String(x.id)===String(S.game.id));if(fresh)S.game={...S.game,...fresh}}if(renderAfter&&(S.route==='games'||S.route==='intel'))render();else{let r=document.querySelector('#liveRibbon');if(r){r.outerHTML=liveRibbon();wireLiveRibbon()}}}catch(e){S.online=false;let r=document.querySelector('#liveRibbon');if(r){r.outerHTML=liveRibbon();wireLiveRibbon()}}}
function gamePulseMs(){let c=gameCounts(S.games);return c.live?8000:c.pre?30000:60000}
function startGameDayPulse(){clearTimeout(window._atlasGamePulse);let tick=async()=>{if(!document.hidden&&['games','intel','home','forecast'].includes(S.route)){await refreshGameDay(S.route==='games');if(S.route==='intel'&&S.game?.id){try{S.game=await api('/api/game?id='+S.game.id,{tries:1,timeout:6500,force:true});await intel()}catch{}}}window._atlasGamePulse=setTimeout(tick,gamePulseMs())};window._atlasGamePulse=setTimeout(tick,gamePulseMs())}
function shell(body){A.innerHTML=`<div class="app"><header class="top"><div class="brand"><i class="mark"></i><span>ATLAS</span><span class="muted mono">39</span></div><nav class="nav">${[['home','Home'],['games','Games'],['league','League'],['teams','Teams'],['players','Players'],['intel','Intelligence'],['gm','Front Office'],['compare','Compare'],['brain','Live Brain'],['studio','Graph Studio'],['forecast','Forecasts'],['data','Data']].map(([r,l])=>`<button data-go="${r}" class="${S.route===r?'on':''}">${l}</button>`).join('')}</nav><button class="quickSearch" id="quickSearch" title="Search ATLAS">⌕ <span>Search</span><kbd>/</kbd></button><div class="coverage mono" title="NFL directory integrity">32/32</div><div class="sysclock mono" id="sysclock">--:--</div><button class="densityKey" id="densityKey" title="Toggle interface density">VIEW</button><button class="cmdkey" id="cmdkey">⌘K</button><i class="statusdot" title="system"></i></header><div class="cornerHUD"><span>ATLAS//39</span><i></i><span>GAME DAY FINAL</span></div>${liveRibbon()}${body}</div>`;document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go));let tick=()=>{let e=document.querySelector('#sysclock');if(e)e.textContent=new Date().toLocaleTimeString([], {hour12:false})};tick();clearInterval(window._atlasClock);window._atlasClock=setInterval(tick,1000);document.querySelector('#cmdkey')?.addEventListener('click',commandDeck);document.querySelector('#quickSearch')?.addEventListener('click',globalSearch);document.body.dataset.density=S.density;wireLiveRibbon();startGameDayPulse();document.querySelector('#densityKey')?.addEventListener('click',()=>{S.density=S.density==='compact'?'comfort':'compact';localStorage.setItem('atlas-density',S.density);document.body.dataset.density=S.density})}
function commandDeck(){let old=document.querySelector('.commandDeck');if(old){old.remove();return}let d=document.createElement('div');d.className='commandDeck';d.innerHTML=`<div class="commandBox"><div class="eyebrow lime">ATLAS COMMAND DECK</div><h2>Jump anywhere.</h2>${[['home','01','Home'],['games','02','Game Center'],['league','03','League Landscape'],['teams','04','Team Command'],['players','05','Scouting Index'],['intel','06','Game Room'],['gm','07','Front Office'],['compare','08','Compare Lab'],['brain','09','Live Brain'],['studio','10','Graph Studio'],['data','11','Data Fabric']].map(x=>`<button data-cmd="${x[0]}"><span>${x[1]}</span>${x[2]}<i>↗</i></button>`).join('')}<small>ESC TO CLOSE · CTRL/⌘ + K TO TOGGLE</small></div>`;document.body.appendChild(d);d.onclick=e=>{if(e.target===d)d.remove()};d.querySelectorAll('[data-cmd]').forEach(x=>x.onclick=()=>{d.remove();go(x.dataset.cmd)})}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();commandDeck()}if(e.key==='Escape')document.querySelector('.commandDeck')?.remove()});
function go(r,extra){S.route=r;if(extra)Object.assign(S,extra);location.hash=r;render()}
async function ensure(kind){try{if(kind==='teams'&&!S.teams.length){S.teams=(await api('/api/teams')).teams||[];S.teams=S.teams.map(t=>({...t,abbr:normAb(t.abbr)}))}if(kind==='league'&&!S.league){S.league=await api('/api/league');S.league.standings=(S.league.standings||[]).map(r=>({...r,abbr:normAb(r.abbr)}));}if(kind==='players'&&!S.players.length)S.players=(await api('/api/players')).players||[];if(kind==='games'&&!S.games.length)S.games=(await api('/api/week?season=2026&type=2')).games||[];if(kind==='health'&&!S.health)S.health=await api('/api/health')}catch(e){console.warn(e)}}
function logo(ab){return S.teams.find(t=>t.abbr===ab)?.logo||`https://a.espncdn.com/i/teamlogos/nfl/500/${ab==='LA'?'lar':ab==='WAS'?'wsh':ab.toLowerCase()}.png`}
function num(v){let n=parseFloat(String(v??'').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:0}
function bars(rows,label='VALUE'){let max=Math.max(1,...rows.map(x=>Math.abs(num(x.v))));return `<div class="viz bars"><div class="vizTop"><span>${esc(label)}</span><span>LIVE DATA</span></div>${rows.map(x=>`<div class="barrow"><span>${esc(x.k)}</span><i><b style="width:${Math.max(2,Math.abs(num(x.v))/max*100)}%"></b></i><strong>${esc(x.v)}</strong></div>`).join('')}</div>`}
function spark(vals){let a=vals.map(num),w=420,h=120,min=Math.min(...a,0),max=Math.max(...a,1),span=max-min||1,pts=a.map((v,i)=>`${i*(w/(Math.max(1,a.length-1)))},${h-((v-min)/span)*(h-18)-9}`).join(' ');return `<svg class="spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="sg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c7ff45" stop-opacity=".35"/><stop offset="1" stop-color="#c7ff45" stop-opacity="0"/></linearGradient></defs><polyline points="0,${h} ${pts} ${w},${h}" fill="url(#sg)" stroke="none"/><polyline points="${pts}" fill="none" stroke="#c7ff45" stroke-width="3" vector-effect="non-scaling-stroke"/></svg>`}
function donut(rows,label='MIX'){let total=Math.max(1,rows.reduce((a,x)=>a+Math.max(0,num(x.v)),0)),off=0;let seg=rows.slice(0,8).map((x,i)=>{let v=Math.max(0,num(x.v)),pct=v/total*100,d=`${pct} ${100-pct}`,o=-off;off+=pct;return `<circle cx="60" cy="60" r="48" pathLength="100" fill="none" stroke="hsl(${78+i*21} 72% ${52-i*2}%)" stroke-width="12" stroke-dasharray="${d}" stroke-dashoffset="${o}"/>`}).join('');return `<div class="donutViz"><svg viewBox="0 0 120 120">${seg}<circle cx="60" cy="60" r="34" class="donutCore"/></svg><div><span class="eyebrow">${esc(label)}</span><strong>${total}</strong>${rows.slice(0,6).map((x,i)=>`<small><i style="--h:${78+i*21}"></i>${esc(x.k)} <b>${esc(x.v)}</b></small>`).join('')}</div></div>`}
function scatter(rows){let clean=rows.map(x=>({k:x.abbr||x.k,x:num(x.wins??x.winPct??x.x),y:num(x.diff??x.y)})).filter(x=>Number.isFinite(x.x)&&Number.isFinite(x.y));if(!clean.length)return '<div class="empty">Not enough standings data for scatter.</div>';let maxX=Math.max(1,...clean.map(x=>x.x)),minY=Math.min(0,...clean.map(x=>x.y)),maxY=Math.max(1,...clean.map(x=>x.y)),span=maxY-minY||1;return `<div class="scatter"><div class="axis yaxis">POINT DIFF ↑</div><div class="axis xaxis">WINS →</div><i class="zero" style="top:${100-(0-minY)/span*100}%"></i>${clean.map(x=>`<b title="${esc(x.k)} · ${x.x} wins · ${x.y} diff" style="left:${x.x/maxX*92+4}%;top:${96-(x.y-minY)/span*90}%"><span>${esc(x.k)}</span></b>`).join('')}</div>`}
function heat(rows){let max=Math.max(1,...rows.map(x=>num(x.v)));return `<div class="heat">${rows.map(x=>{let q=Math.max(.08,num(x.v)/max);return `<div style="--q:${q}"><span>${esc(x.k)}</span><b>${esc(x.v)}</b></div>`}).join('')}</div>`}
function quarterChart(plays){let q=[1,2,3,4].map(n=>({k:'Q'+n,v:plays.filter(p=>num(p.period)===n).length}));return bars(q,'CAPTURED PLAYS BY QUARTER')}
function techTitle(k,t,sub=''){return `<div class="techTitle"><span class="cross">+</span><div><div class="eyebrow">${esc(k)}</div><h2>${esc(t)}</h2>${sub?`<small>${esc(sub)}</small>`:''}</div><span class="coordinates mono">SYS // ${String(Date.now()).slice(-6)}</span></div>`}
function home(){shell(`<main class="page home"><div class="homegrid"><section><div class="eyebrow lime">ATLAS · FOOTBALL INTELLIGENCE</div><h1>Know the game<br><i>before the story</i><br>is written.</h1><p class="lede">One operating surface for the NFL. Live games, league structure, player discovery, club intelligence and front-office work—without turning football into a spreadsheet.</p><div class="cta"><button class="btn" data-homego="games">Open Game Center</button><button class="btn ghost" data-homego="league">Explore the league</button></div></section><div class="fieldart"><div class="yard"></div></div></div><div class="strip"><span class="eyebrow">THE 2026 SEASON</span><span class="mono muted">LIVE DATA · ARCHIVE · PERSONNEL · RESEARCH</span></div>${myAtlas()}</main>`);document.querySelectorAll('[data-homego]').forEach(x=>x.onclick=()=>go(x.dataset.homego))}
async function games(){await ensure('teams');await ensure('games');let gs=S.games||[];let active=S.game||gs[0];shell(`<main class="page games"><div class="workspaceHead"><div><div class="eyebrow">GAME CENTER / 2026</div><h1>The week,<br><i>at a glance.</i></h1></div><div class="mono">${gs.length} GAMES IN FEED</div></div>${gameDayBar(gs)}<div class="gameRail">${gs.map(g=>ticket(g,active?.id===g.id)).join('')||'<div class="empty">No schedule returned.</div>'}</div>${active?feature(active):'<div class="empty">Select a game.</div>'}</main>`);document.querySelectorAll('[data-game]').forEach(x=>x.onclick=()=>{S.game=gs.find(g=>String(g.id)===x.dataset.game);games()});document.querySelector('[data-openintel]')?.addEventListener('click',()=>go('intel'))}
function sides(g){let ts=g.teams||[];return [ts.find(t=>t.side==='away')||ts[0]||{},ts.find(t=>t.side==='home')||ts[1]||{}]}
function ticket(g,on){let [a,h]=sides(g);return `<button class="gameTicket ${on?'active':''}" data-game="${esc(g.id)}"><div class="eyebrow">${esc(g.status||g.state||'SCHEDULED')}</div><div class="teams"><span>${esc(a.abbr||a.name)}</span><span>${esc(a.score||'')}</span><span>${esc(h.abbr||h.name)}</span><span>${esc(h.score||'')}</span></div></button>`}
function feature(g){let[a,h]=sides(g);return `<div class="featureGame"><div class="featureTeam"><img src="${esc(a.logo||logo(a.abbr))}"><h2>${esc(a.name||a.abbr)}</h2><div class="score">${esc(a.score||'—')}</div></div><div><div class="gameMeta">${esc(g.status)}<br>${esc(g.date||'')}</div><button class="btn ghost" style="color:#111;border-color:#111;margin-top:18px" data-openintel>OPEN GAME ROOM</button></div><div class="featureTeam"><img src="${esc(h.logo||logo(h.abbr))}"><h2>${esc(h.name||h.abbr)}</h2><div class="score">${esc(h.score||'—')}</div></div></div>`}
async function league(){await ensure('teams');await ensure('league');let st=S.league?.standings||[],map=Object.fromEntries(st.map(x=>[x.abbr,x]));shell(`<main class="page league"><div class="leagueHero"><div><div class="eyebrow lime">NFL LANDSCAPE / 2026</div><h1>Thirty-two clubs.<br>One landscape.</h1><div class="integrityChip"><i></i> 32-TEAM DIRECTORY VERIFIED</div></div><p class="lede">Standings are arranged as football is actually organized: conference, division, club. Open any crest to enter its command center.</p></div>${['AFC','NFC'].map(conf=>`<section class="conference"><div class="confTitle">${conf} / FOUR DIVISIONS</div><div class="divisionGrid">${Object.entries(ALIGN).filter(([d])=>d.startsWith(conf)).map(([d,abs])=>`<div class="division"><h3>${d.replace(conf+' ','')}</h3>${abs.map(ab=>{let r=map[ab]||{},t=S.teams.find(x=>x.abbr===ab)||{};return `<button class="club" data-club="${ab}"><img src="${esc(r.logo||t.logo||logo(ab))}"><span><b>${esc(t.name||r.name||ab)}</b><small>${esc(r.streak||'')}</small></span><span class="record">${esc(r.record||'—')}</span></button>`}).join('')}</div>`).join('')}</div></section>`).join('')}<section class="leaguePulse"><div><span>CLUB DIRECTORY</span><b>32</b><small>All NFL teams</small></div><div><span>STANDINGS FEED</span><b>${st.length}</b><small>Normalized ESPN rows</small></div><div><span>CONFERENCES</span><b>2</b><small>16 clubs each</small></div><div><span>DIVISIONS</span><b>8</b><small>4 clubs each</small></div></section><section class="analyticsLab">${techTitle('LEAGUE TELEMETRY','Performance distribution','Point differential from the live standings feed')}<div class="graphGrid"><div>${bars(st.slice().sort((a,b)=>num(b.diff)-num(a.diff)).slice(0,12).map(x=>({k:x.abbr,v:x.diff||0})),'POINT DIFFERENTIAL')}</div><div><div class="vizTop"><span>WINS × POINT DIFFERENTIAL</span><span>32 CLUB FIELD</span></div>${scatter(st)}</div><div>${donut([{k:'AFC',v:16},{k:'NFC',v:16}],'LEAGUE SPLIT')}</div><div class="tracePanel"><span class="eyebrow">RANK-ORDER DIFFERENTIAL TRACE</span>${spark(st.slice().sort((a,b)=>num(a.rank)-num(b.rank)).map(x=>num(x.diff)))}</div></div></section></main>`);document.querySelectorAll('[data-club]').forEach(x=>x.onclick=()=>go('teams',{team:x.dataset.club}))}
async function teams(){await ensure('teams');await ensure('league');let ab=S.team||'SF',t=S.teams.find(x=>x.abbr===ab)||{},r=(S.league?.standings||[]).find(x=>x.abbr===ab)||{},leaders=S.league?.teamLeaders?.[ab]||[];let roster={players:[]},ta={stats:[]};try{[roster,ta]=await Promise.all([api('/api/roster?team='+ab),api('/api/teamstats?team='+ab)])}catch{}let statRows=metricRows(ta.stats);let ps=roster.players||[],groups={};ps.forEach(p=>(groups[p.position||'OTHER']??=[]).push(p));let order=['QB','RB','WR','TE','OT','G','C','DE','DT','LB','CB','S','K','P'];shell(`<main class="page teamsPage"><section class="teamHero" style="--tc:${TEAM_COLORS[ab]||'#333'}"><img class="watermark" src="${esc(t.logo||logo(ab))}"><div class="teamHeroContent"><select class="teamPick" id="teamPick">${S.teams.map(x=>`<option value="${x.abbr}" ${x.abbr===ab?'selected':''}>${esc(x.name)}</option>`).join('')}</select><div class="eyebrow" style="margin-top:25px">${esc(r.record||'2026')} · ${esc(Object.keys(ALIGN).find(k=>ALIGN[k].includes(ab))||'NFL')}</div><h1>${esc((t.name||ab).replace(/^[A-Za-z .]+ /,''))}</h1><div class="mono">${esc(t.name||ab)} / ${ps.length} ACTIVE ROSTER ENTRIES</div></div></section><section class="teamDeck"><div><div class="eyebrow lime" style="margin-bottom:12px">ROSTER ARCHITECTURE</div><div class="positionMap">${order.filter(k=>groups[k]?.length).map(k=>`<div class="room"><span>${k}</span><strong>${groups[k].length}</strong><small class="muted">${groups[k].slice(0,3).map(p=>esc(p.name)).join('<br>')}</small></div>`).join('')||'<div class="room">Roster unavailable</div>'}</div><div class="teamGraphs">${bars(order.filter(k=>groups[k]?.length).map(k=>({k,v:groups[k].length})),'ROSTER BY POSITION')}${donut(order.filter(k=>groups[k]?.length).map(k=>({k,v:groups[k].length})),'POSITION MIX')}${heat(order.filter(k=>groups[k]?.length).map(k=>({k,v:groups[k].length})))}</div></div><aside><div class="eyebrow lime">SEASON SIGNALS</div><div class="leaders">${leaders.slice(0,8).map(l=>`<div class="leader"><span><b>${esc(l.name)}</b><br><small class="muted">${esc(l.category)}</small></span><b class="mono">${esc(l.value)}</b></div>`).join('')||'<div class="empty">Season leaders not returned.</div>'}</div></aside></section><section class="profileAnalytics">${techTitle('TEAM ANALYTICS LAB','Season fingerprint','Verified team-season statistics; relative shapes are within this club')}<div class="graphGrid two"><div>${bars(statRows.slice(0,12),'TEAM METRICS')}</div><div>${statRadar(statRows)}</div></div>${percentileBars(statRows)}${provenance(ta.source,ta.updated)}</section></main>`);document.querySelector('#teamPick').onchange=e=>{S.team=e.target.value;teams()}}
async function players(){await ensure('players');let teams=[...new Set(S.players.map(p=>p.team).filter(Boolean))].sort();shell(`<main class="page playersPage"><div class="scoutHead"><div class="eyebrow">SCOUTING INDEX / ${S.players.length} PLAYERS</div><h1>Find the player.<br>Lose the spreadsheet.</h1><div class="searchbar"><input id="pq" placeholder="Search name…"><select id="pp"><option value="">All positions</option>${[...new Set(S.players.map(p=>p.position).filter(Boolean))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="pt"><option value="">All clubs</option>${teams.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div></div><section class="playerTelemetry">${techTitle('DATABASE TELEMETRY','Position population','Verified roster entries in the current player index')}<div class="graphGrid two">${bars(Object.entries(S.players.reduce((a,x)=>{let k=x.position||'OTHER';a[k]=(a[k]||0)+1;return a},{})).sort((a,b)=>b[1]-a[1]).slice(0,12).map(([k,v])=>({k,v})),'PLAYERS')}${donut(Object.entries(S.players.reduce((a,x)=>{let k=x.position||'OTHER';a[k]=(a[k]||0)+1;return a},{})).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([k,v])=>({k,v})),'TOP POSITION MIX')}</div></section><div class="resultBar"><div class="playerCount" id="pc"></div><span class="mono muted">LIVE FILTER · MAX 120 RESULTS</span></div><div class="playerGrid" id="pg"></div></main>`);let draw=()=>{let q=document.querySelector('#pq').value.toLowerCase(),p=document.querySelector('#pp').value,t=document.querySelector('#pt').value;let rows=S.players.filter(x=>(!q||(x.name||'').toLowerCase().includes(q))&&(!p||x.position===p)&&(!t||x.team===t)).slice(0,120);document.querySelector('#pc').textContent=`SHOWING ${rows.length} / ${S.players.length}`;document.querySelector('#pg').innerHTML=rows.map((x,i)=>`<button class="playerCard" data-player="${esc(x.id)}"><span class="num">${String(i+1).padStart(2,'0')}</span><h3>${esc(x.name)}</h3><small>${esc(x.team)} / ${esc(x.position)} ${x.starter?' / STARTER':''}</small></button>`).join('')};['pq','pp','pt'].forEach(id=>document.querySelector('#'+id).oninput=draw);draw();document.querySelector('#pg').onclick=e=>{let c=e.target.closest('[data-player]');if(c)playerProfile(c.dataset.player)}}
async function intel(){await ensure('teams');await ensure('games');let g=S.game||S.games[0];if(!g){shell('<main class="intel"><div class="empty">No game selected.</div></main>');return}try{S.game=await api('/api/game?id='+g.id);g=S.game}catch{}let[a,h]=sides(g),plays=g.plays||[];shell(`<main class="page intel"><section class="intelScore"><div class="intelTeam"><img src="${esc(a.logo||logo(a.abbr))}"><h2>${esc(a.name||a.abbr)}</h2><div class="score">${esc(a.score||'—')}</div></div><div><div class="eyebrow" style="color:#ff593d">GAME ROOM</div><div class="vs">@</div><div class="mono muted">${esc(g.status||'')}</div></div><div class="intelTeam"><img src="${esc(h.logo||logo(h.abbr))}"><h2>${esc(h.name||h.abbr)}</h2><div class="score">${esc(h.score||'—')}</div></div></section><div class="field"></div><section class="gameTelemetry">${techTitle('GAME TELEMETRY','Captured game shape','Charts only reflect plays currently stored by ATLAS')}<div class="graphGrid two">${quarterChart(plays)}${donut([1,2,3,4].map(n=>({k:'Q'+n,v:plays.filter(p=>num(p.period)===n).length})),'PLAY SHARE')}</div></section><section class="playfeed"><h3>PLAY TAPE</h3><div>${plays.length?plays.slice(-30).reverse().map(p=>`<div class="play"><small class="mono muted">Q${esc(p.period)} · ${esc(p.clock)} · ${esc(p.team||'')}</small><br>${esc(p.text||'Play')}</div>`).join(''):`<div class="empty">${String(g.state||'').toLowerCase()==='pre'?'Live models and play tape activate at kickoff.':'No captured play feed available.'}</div>`}</div></section></main>`)}
async function gm(){await ensure('teams');let ab=S.team||'SF';let roster={players:[]},ta={stats:[]};try{[roster,ta]=await Promise.all([api('/api/roster?team='+ab),api('/api/teamstats?team='+ab)])}catch{}let statRows=metricRows(ta.stats);let ps=roster.players||[],groups={};ps.forEach(p=>(groups[p.position||'OTHER']??=[]).push(p));let rooms=Object.entries(groups).sort((a,b)=>b[1].length-a[1].length);shell(`<main class="page gm"><div class="gmTop"><div><div class="eyebrow">FRONT OFFICE / PERSONNEL BOARD</div><h1>Build the room.</h1></div><div class="mono">${ab} · ${ps.length} ROSTER ENTRIES</div></div><div class="clubrail">${S.teams.map(t=>`<button class="clubchip ${t.abbr===ab?'active':''}" data-gmclub="${t.abbr}"><img src="${esc(t.logo)}"><br><small>${t.abbr}</small></button>`).join('')}</div><div class="board"><section><div class="eyebrow" style="margin-bottom:15px">POSITION ROOMS</div><div class="depthBoard">${rooms.map(([pos,arr])=>`<div class="depth"><h3>${esc(pos)} / ${arr.length}</h3>${arr.slice(0,5).map(p=>`<div class="person"><b>${esc(p.name)}</b>${p.starter?' · STARTER':''}</div>`).join('')}</div>`).join('')||'<div class="empty">Roster feed unavailable.</div>'}</div>${bars(rooms.slice(0,12).map(([k,a])=>({k,v:a.length})),'ROOM SIZE')}${heat(rooms.slice(0,16).map(([k,a])=>({k,v:a.length})))}</section><aside class="memo"><div class="eyebrow">GM MEMO</div><h2 class="serif" style="font-size:42px">Personnel, not pretend grades.</h2><p>ATLAS only shows roster structure the provider actually returns. Missing depth-chart data stays missing; it is never converted into a fake weakness score.</p><p class="mono">CLUB ${ab}<br>ROSTER ${ps.length}<br>ROOMS ${rooms.length}</p></aside></div></main>`);document.querySelectorAll('[data-gmclub]').forEach(x=>x.onclick=()=>{S.team=x.dataset.gmclub;gm()})}
async function dataPage(){await ensure('health');let src={sources:[]};try{src=await api('/api/sources')}catch{}let arr=Array.isArray(src)?src:(src.sources||src.checks||[]);shell(`<main class="page dataPage"><div class="eyebrow">ATLAS 31 / DATA FABRIC / OPERATIONS</div><h1>THE PIPELINE<br>IS THE PRODUCT.</h1><div class="pipeline"><div class="node"><span>01 / FEEDS</span><h2>ESPN PUBLIC</h2><small>Scoreboard · standings · teams · rosters</small></div><div class="arrow">→</div><div class="node"><span>02 / COLLECT</span><h2>${esc(S.health?.collector_seconds||30)} SEC</h2><small>Live collection + archive</small></div><div class="arrow">→</div><div class="node"><span>03 / STORE</span><h2>${esc(S.health?.database||'—')}</h2><small>Games · snapshots · history</small></div><div class="arrow">→</div><div class="node"><span>04 / ATLAS</span><h2>CLIENT</h2><small>Truth-preserving presentation</small></div></div><section class="telemetryStrip"><div><span>COLLECTOR INTERVAL</span><b>${esc(S.health?.collector_seconds||30)}s</b></div><div><span>SOURCE NODES</span><b>${arr.length||1}</b></div><div><span>DATABASE</span><b>${esc(S.health?.database||'—')}</b></div><div class="pulseScope">${spark((arr.length?arr:[{ok:true}]).map(x=>x.ok===false?0:1))}</div></section><div class="opsLegend"><span><i class="okdot"></i> OPERATIONAL</span><span><i class="refdot"></i> REFERENCE</span><span>NO CREDENTIALS STORED IN CLIENT</span></div><div class="sourceGrid">${arr.length?arr.map(s=>`<div class="source"><span class="${s.ok===false?'bad':'ok'}">● ${s.ok===false?'FAULT':'ONLINE'}</span><h3>${esc(s.name||s.label||s.source||'SOURCE')}</h3><small>${esc(s.note||s.status||s.url||'')}</small></div>`).join(''):`<div class="source"><span class="ok">● CORE ONLINE</span><h3>${esc(S.health?.provider||'PROVIDER')}</h3><small>Source diagnostics available through /api/sources</small></div>`}</div></main>`)}

function pin(type,id,label){let key=type+':'+id,idx=S.pins.findIndex(x=>x.key===key);if(idx>=0)S.pins.splice(idx,1);else S.pins.unshift({key,type,id,label});S.pins=S.pins.slice(0,18);localStorage.setItem('atlas-pins',JSON.stringify(S.pins));render()}
function pinned(type,id){return S.pins.some(x=>x.key===type+':'+id)}
function provenance(source,updated,derived=false){return `<div class="provenance"><span>${derived?'ATLAS DERIVED':'RAW / VERIFIED'}</span><b>${esc(source||'ATLAS DATA')}</b>${updated?`<small>UPDATED ${new Date(updated*1000).toLocaleString()}</small>`:''}</div>`}
function metricRows(stats){return (stats||[]).map(x=>({k:x.label||x.name||x.abbr||'Metric',v:x.value??x.displayValue,cat:x.category||''})).filter(x=>x.k&&x.v!==undefined&&x.v!==null)}
function statRadar(rows){let r=rows.filter(x=>Number.isFinite(num(x.v))).slice(0,8);if(r.length<3)return '<div class="empty">Not enough numeric metrics for profile radar.</div>';let vals=r.map(x=>Math.abs(num(x.v))),mx=Math.max(...vals,1),cx=120,cy=120,rad=92;let pts=r.map((x,i)=>{let a=-Math.PI/2+i*2*Math.PI/r.length,rr=18+(Math.abs(num(x.v))/mx)*74;return `${cx+Math.cos(a)*rr},${cy+Math.sin(a)*rr}`}).join(' ');let axes=r.map((x,i)=>{let a=-Math.PI/2+i*2*Math.PI/r.length;return `<line x1="${cx}" y1="${cy}" x2="${cx+Math.cos(a)*rad}" y2="${cy+Math.sin(a)*rad}"/><text x="${cx+Math.cos(a)*108}" y="${cy+Math.sin(a)*108}">${esc(String(x.k).slice(0,11))}</text>`}).join('');return `<div class="radar"><svg viewBox="0 0 240 240"><circle cx="120" cy="120" r="92"/><circle cx="120" cy="120" r="62"/><circle cx="120" cy="120" r="32"/>${axes}<polygon points="${pts}"/></svg></div>`}
function percentileBars(rows){let r=rows.filter(x=>Number.isFinite(num(x.v))).slice(0,10),vals=r.map(x=>Math.abs(num(x.v))),mx=Math.max(...vals,1);return `<div class="percentiles">${r.map(x=>`<div><span>${esc(x.k)}</span><i><b style="width:${Math.max(2,Math.abs(num(x.v))/mx*100)}%"></b></i><strong>${esc(x.v)}</strong></div>`).join('')}</div>`}
async function teamAnalytics(ab){let d={stats:[]};try{d=await api('/api/teamstats?team='+ab)}catch{}let rows=metricRows(d.stats);return {d,rows}}
async function compare(){await ensure('teams');await ensure('league');let a=S.team||'SF',b=S.compareTeam||'KC';if(a===b)b=S.teams.find(x=>x.abbr!==a)?.abbr||'KC';let [aa,bb]=await Promise.all([teamAnalytics(a),teamAnalytics(b)]),ra=(S.league?.standings||[]).find(x=>x.abbr===a)||{},rb=(S.league?.standings||[]).find(x=>x.abbr===b)||{};let amap=Object.fromEntries(aa.rows.map(x=>[x.k,x])),bmap=Object.fromEntries(bb.rows.map(x=>[x.k,x])),common=Object.keys(amap).filter(k=>bmap[k]&&Number.isFinite(num(amap[k].v))&&Number.isFinite(num(bmap[k].v))).slice(0,14);shell(`<main class="page comparePage"><div class="compareHero">${techTitle('COMPARE LAB','Club vs. club','Synchronized verified team-season data')}<div class="comparePick"><select id="ca">${S.teams.map(t=>`<option value="${t.abbr}" ${t.abbr===a?'selected':''}>${esc(t.name)}</option>`).join('')}</select><span>VS</span><select id="cb">${S.teams.map(t=>`<option value="${t.abbr}" ${t.abbr===b?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div></div><section class="compareScore"><div><img src="${logo(a)}"><h2>${a}</h2><b>${esc(ra.record||'—')}</b><small>DIFF ${esc(ra.diff??'—')}</small></div><div class="versusLine"></div><div><img src="${logo(b)}"><h2>${b}</h2><b>${esc(rb.record||'—')}</b><small>DIFF ${esc(rb.diff??'—')}</small></div></section><section class="compareMetrics">${common.length?common.map(k=>{let av=num(amap[k].v),bv=num(bmap[k].v),mx=Math.max(Math.abs(av),Math.abs(bv),1);return `<div class="metricDuel"><span>${esc(k)}</span><div class="duel"><b style="width:${Math.abs(av)/mx*100}%"></b><i>${esc(amap[k].v)}</i></div><div class="duel right"><b style="width:${Math.abs(bv)/mx*100}%"></b><i>${esc(bmap[k].v)}</i></div></div>`}).join(''):'<div class="empty">No common numeric season metrics returned for these clubs.</div>'}</section><div class="graphGrid two"><div>${statRadar(aa.rows)}${provenance(aa.d.source,aa.d.updated)}</div><div>${statRadar(bb.rows)}${provenance(bb.d.source,bb.d.updated)}</div></div></main>`);document.querySelector('#ca').onchange=e=>{S.team=e.target.value;compare()};document.querySelector('#cb').onchange=e=>{S.compareTeam=e.target.value;compare()}}
async function playerProfile(id){let d;try{d=await api('/api/player?id='+id)}catch{};let p=d?.player;if(!p)return;let rows=metricRows(p.stats);shell(`<main class="page playerProfile"><button class="backBtn" id="backPlayers">← SCOUTING INDEX</button><section class="profileHero" style="--tc:${TEAM_COLORS[normAb(p.team)]||'#222'}"><div>${p.headshot?`<img src="${esc(p.headshot)}">`:''}</div><div><div class="eyebrow">${esc(p.team)} / ${esc(p.position)} / #${esc(p.jersey||'—')}</div><h1>${esc(p.name)}</h1><p>${esc(p.height||'')} · ${esc(p.weight||'')} · ${p.experience!=null?esc(p.experience)+' YRS':''} ${p.college?'· '+esc(p.college):''}</p><button class="pinBtn" id="pinPlayer">${pinned('player',p.id)?'★ PINNED':'☆ PIN PLAYER'}</button></div></section><section class="profileAnalytics">${techTitle('PLAYER LAB','Verified season profile',p.stats_status==='verified'?'Season statistics returned by source':'Season stats unavailable')}<div class="graphGrid two"><div>${bars(rows.slice(0,12),'SEASON METRICS')}</div><div>${statRadar(rows)}</div></div>${percentileBars(rows)}${provenance(p.stats_source,d.updated)}</section><section class="gameLog"><h3>GAME LOG / ARCHIVE</h3>${(p.gamelog||p.archive_games||[]).slice(0,12).map(g=>`<div><span>${esc(g.date||g.game_id||'GAME')}</span><b>${esc(g.opponent||g.status||'')}</b></div>`).join('')||'<div class="empty">No game-log rows available.</div>'}</section></main>`);document.querySelector('#backPlayers').onclick=()=>go('players');document.querySelector('#pinPlayer').onclick=()=>pin('player',p.id,p.name)}
function myAtlas(){let pins=S.pins||[];return `<section class="myAtlas"><div class="eyebrow lime">MY ATLAS</div><div class="pinRail">${pins.length?pins.map(x=>`<button data-pinopen="${esc(x.key)}"><span>${x.type.toUpperCase()}</span><b>${esc(x.label)}</b></button>`).join(''):'<small class="muted">Pin players from Player Lab to build your desk.</small>'}</div></section>`}
async function render(){A.innerHTML='<div class="loading">ATLAS / LOADING WORKSPACE</div>';if(S.route==='home')return home33();if(S.route==='games')return games();if(S.route==='league')return league();if(S.route==='teams')return teams();if(S.route==='players')return players();if(S.route==='intel')return intel33();if(S.route==='gm')return gm();if(S.route==='compare')return compare();if(S.route==='brain')return brain();if(S.route==='studio')return studio();if(S.route==='forecast')return forecast();if(S.route==='data')return dataPage33();home33()}
S.route=(location.hash||'#home').slice(1).split('/')[0]||'home';window.onhashchange=()=>{S.route=(location.hash||'#home').slice(1).split('/')[0]||'home';render()};render();

window.addEventListener('keydown',e=>{if(e.key==='/'&&S.route==='players'&&!/INPUT|SELECT|TEXTAREA/.test(document.activeElement?.tagName)){e.preventDefault();document.querySelector('#pq')?.focus()}if(e.key==='Escape')document.querySelector('.commandDeck')?.remove()});


function lineGraph(rows,keys,title){if(!rows.length)return '<div class="empty">No archived trend rows yet.</div>';let w=760,h=250,p=30,all=rows.flatMap(r=>keys.map(k=>num(r[k]))),mn=Math.min(0,...all),mx=Math.max(1,...all),span=mx-mn||1;let paths=keys.map((k,ki)=>{let pts=rows.map((r,i)=>`${p+i*(w-p*2)/Math.max(1,rows.length-1)},${h-p-(num(r[k])-mn)/span*(h-p*2)}`).join(' ');return `<polyline class="trendLine l${ki}" points="${pts}"/>`}).join('');return `<div class="trendCard"><div class="vizTop"><span>${esc(title)}</span><span>${rows.length} STORED GAMES</span></div><svg class="trendSvg" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" class="gridLine"/>${paths}</svg><div class="trendLegend">${keys.map((k,i)=>`<span><i class="lg${i}"></i>${esc(k.replaceAll('_',' ').toUpperCase())}</span>`).join('')}</div></div>`}
function insightCards(d){return `<div class="insightGrid">${(d.insights||[]).map(x=>`<article><span>ATLAS OBSERVATION</span><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p>${x.game_id?`<button data-replay="${esc(x.game_id)}">OPEN EVIDENCE ↗</button>`:''}</article>`).join('')||'<div class="empty">Insights appear as final games accumulate in the ATLAS archive.</div>'}</div>`}
async function home33(){await ensure('teams');let recent={games:[]},cov={},ins={insights:[]};try{[recent,cov,ins]=await Promise.all([api('/api/recent?limit=4'),api('/api/archive-coverage'),api('/api/insights')])}catch{}shell(`<main class="page home home33"><div class="homegrid"><section><div class="eyebrow lime">ATLAS 37 · GAME DAY FINAL</div><h1>Know the game<br><i>before the story</i><br>is written.</h1><p class="lede">The archive now feeds trends, replay, factual insights and custom visualization tools automatically.</p><div class="cta"><button class="btn" data-homego="brain">Open Live Brain</button><button class="btn ghost" data-homego="studio">Graph Studio</button></div></section><div class="brainCore"><div class="orb"><i></i><b>LIVE<br>BRAIN</b></div><div class="brainStats"><span>ARCHIVED <b>${esc(cov.archived??'—')}</b></span><span>MISSING <b>${esc(cov.missing??'—')}</b></span><span>RECENT <b>${recent.games?.length||0}</b></span></div></div></div>${myAtlas()}<section class="recentDesk">${techTitle('AUTOMATIC ARCHIVE','Recent finals','Captured without opening each game')}${(recent.games||[]).map(g=>{let [a,h]=sides(g);return `<button data-replay="${g.id}"><span>${esc(a.abbr)} ${esc(a.score)} — ${esc(h.score)} ${esc(h.abbr)}</span><small>${esc(g.status)} · ${esc(g.quality?.label||'ARCHIVED')}</small></button>`}).join('')||'<div class="empty">No completed games stored yet.</div>'}</section>${insightCards(ins)}</main>`);wire33()}
async function brain(){await ensure('teams');let ab=S.team||'SF',trend={games:[]},ins={insights:[]},cov={},recent={games:[]};try{[trend,ins,cov,recent]=await Promise.all([api('/api/trends?team='+ab),api('/api/insights?team='+ab),api('/api/archive-coverage'),api('/api/recent?limit=12')])}catch{}let rows=trend.games||[];shell(`<main class="page brainPage">${techTitle('LIVE BRAIN','The archive thinks in trends.','Only completed games stored by ATLAS are analyzed.')}<div class="brainControls"><select id="brainTeam">${S.teams.map(t=>`<option value="${t.abbr}" ${t.abbr===ab?'selected':''}>${esc(t.name)}</option>`).join('')}</select><div><span>ARCHIVE COVERAGE</span><b>${esc(cov.archived??0)} / ${esc(cov.expected_finals??0)}</b></div><div><span>AUTO-BACKFILL</span><b>${cov.missing?'RECOVERING':'CLEAR'}</b></div></div><div class="graphGrid two">${lineGraph(rows,['points_for','points_against'],'SCORING TREND')}${lineGraph(rows,['margin'],'GAME MARGIN')}</div>${rows.length?bars(rows.slice(-8).map((r,i)=>({k:r.opponent||('G'+(i+1)),v:r.margin})),'RECENT MARGIN'):''}<section>${techTitle('ATLAS INSIGHTS','What changed','Deterministic observations with evidence')}${insightCards(ins)}</section><section>${techTitle('ARCHIVE VAULT','Stored finals','Open any stored game in Replay') }<div class="vault">${(recent.games||[]).map(g=>{let[a,h]=sides(g);return `<button data-replay="${g.id}"><b>${esc(a.abbr)} ${esc(a.score)} <i>@</i> ${esc(h.abbr)} ${esc(h.score)}</b><small>${esc(g.date||g.status)} · ${g.plays||0} PLAYS · ${esc(g.quality?.label||'')}</small></button>`}).join('')||'<div class="empty">Archive empty.</div>'}</div></section>${provenance(trend.source,trend.updated,true)}</main>`);document.querySelector('#brainTeam').onchange=e=>{S.team=e.target.value;brain()};wire33()}
async function replay(gid){let g={},hist={snapshots:[]};try{[g,hist]=await Promise.all([api('/api/game?id='+gid),api('/api/history?id='+gid)])}catch{}let snaps=hist.snapshots||[],[a,h]=sides(g);shell(`<main class="page replayPage"><button class="backBtn" id="backBrain">← LIVE BRAIN</button>${techTitle('GAME REPLAY',`${a.abbr||'?'} @ ${h.abbr||'?'}`,g.status||'Stored game')}<section class="replayScore"><div><img src="${esc(a.logo||logo(a.abbr))}"><b>${esc(a.score)}</b><span>${esc(a.abbr)}</span></div><i>FINAL</i><div><img src="${esc(h.logo||logo(h.abbr))}"><b>${esc(h.score)}</b><span>${esc(h.abbr)}</span></div></section><div class="replayTimeline"><input id="scrub" type="range" min="0" max="${Math.max(0,snaps.length-1)}" value="${Math.max(0,snaps.length-1)}" ${snaps.length?'':'disabled'}><div id="snapRead">${snaps.length?`SNAPSHOT ${snaps.length} / ${snaps.length}`:'No stored snapshots for this game.'}</div></div><div id="replayGraph">${lineGraph(snaps.map((x,i)=>({i,...(x.scores||{})})),[a.abbr,h.abbr],'SCORE SNAPSHOTS')}</div><section class="playfeed"><h3>CAPTURED PLAY TAPE</h3><div>${(g.plays||[]).slice(-40).reverse().map(p=>`<div class="play"><small class="mono muted">Q${esc(p.period)} · ${esc(p.clock)} · ${esc(p.team||'')}</small><br>${esc(p.text||'Play')}</div>`).join('')||'<div class="empty">No play tape stored.</div>'}</div></section>${provenance('ATLAS GAME ARCHIVE',null)}</main>`);document.querySelector('#backBrain').onclick=()=>go('brain');let sl=document.querySelector('#scrub');if(sl)sl.oninput=()=>{let n=+sl.value+1,sp=snaps[+sl.value]||{};document.querySelector('#snapRead').textContent=`SNAPSHOT ${n} / ${snaps.length} · ${new Date((sp.t||0)*1000).toLocaleTimeString()}`}}
async function studio(){await ensure('teams');let ab=S.team||'SF',trend={games:[]};try{trend=await api('/api/trends?team='+ab)}catch{}let rows=trend.games||[],metric=S.studioMetric||'points_for',types=['points_for','points_against','margin','rolling3_pf','rolling3_pa','plays','drives'];shell(`<main class="page studioPage">${techTitle('GRAPH STUDIO','Build the view.','Every point comes from the ATLAS final-game archive.')}<div class="studioControls"><label>CLUB<select id="studioTeam">${S.teams.map(t=>`<option value="${t.abbr}" ${t.abbr===ab?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>METRIC<select id="studioMetric">${types.map(x=>`<option value="${x}" ${x===metric?'selected':''}>${x.replaceAll('_',' ').toUpperCase()}</option>`).join('')}</select></label><button id="saveGraph">☆ SAVE VIEW</button></div><section class="studioCanvas">${lineGraph(rows,[metric],`${ab} · ${metric.replaceAll('_',' ').toUpperCase()}`)}<div class="studioFacts"><span>SAMPLE <b>${rows.length}</b></span><span>SOURCE <b>FINAL ARCHIVE</b></span><span>TYPE <b>TIME SERIES</b></span></div></section><div class="graphTable">${rows.map((r,i)=>`<div><span>${i+1}</span><b>${esc(r.opponent)}</b><em>${esc(r.result)}</em><strong>${esc(r[metric]??'—')}</strong></div>`).join('')||'<div class="empty">No archived games for this club yet.</div>'}</div>${provenance(trend.source,trend.updated,true)}</main>`);document.querySelector('#studioTeam').onchange=e=>{S.team=e.target.value;studio()};document.querySelector('#studioMetric').onchange=e=>{S.studioMetric=e.target.value;studio()};document.querySelector('#saveGraph').onclick=()=>{let saved=JSON.parse(localStorage.getItem('atlas-graphs')||'[]');saved.unshift({team:ab,metric,at:Date.now()});localStorage.setItem('atlas-graphs',JSON.stringify(saved.slice(0,12)));document.querySelector('#saveGraph').textContent='★ SAVED'}}
async function intel33(){if(S.replayId)return replay(S.replayId);return intel()}
async function dataPage33(){await dataPage();let main=document.querySelector('.dataPage');if(!main)return;let cov={};try{cov=await api('/api/archive-coverage')}catch{}main.insertAdjacentHTML('beforeend',`<section class="archiveHealth">${techTitle('ARCHIVE AUTOPILOT','Final-game capture','Automatic recovery scans for missed completed games')}<div class="healthCells"><div><span>EXPECTED FINALS</span><b>${esc(cov.expected_finals??'—')}</b></div><div><span>ARCHIVED</span><b>${esc(cov.archived??'—')}</b></div><div><span>MISSING</span><b>${esc(cov.missing??'—')}</b></div><div><span>PARTIAL</span><b>${esc(cov.partial??'—')}</b></div></div>${cov.weeks?heat(cov.weeks.map(x=>({k:'W'+x.week,v:x.archived}))):''}</section>`)}
function wire33(){document.querySelectorAll('[data-homego]').forEach(x=>x.onclick=()=>go(x.dataset.homego));document.querySelectorAll('[data-replay]').forEach(x=>x.onclick=()=>{S.replayId=x.dataset.replay;S.route='intel';location.hash='intel';render()})}
function globalSearch(){let old=document.querySelector('.globalSearch');if(old){old.remove();return}let d=document.createElement('div');d.className='globalSearch';d.innerHTML=`<div class="searchBox"><div class="eyebrow lime">GLOBAL SEARCH</div><input id="globalQ" placeholder="Team, player, archived game…" autocomplete="off"><div id="globalResults"><small>TYPE 2+ CHARACTERS</small></div></div>`;document.body.appendChild(d);let inp=d.querySelector('#globalQ'),timer;inp.focus();inp.oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{if(inp.value.trim().length<2)return;let r=await api('/api/search?q='+encodeURIComponent(inp.value));d.querySelector('#globalResults').innerHTML=(r.results||[]).map(x=>`<button data-s-type="${x.type}" data-s-id="${esc(x.id)}"><span>${x.type}</span><b>${esc(x.label)}</b><small>${esc(x.meta)}</small></button>`).join('')||'<small>NO MATCHES</small>';d.querySelectorAll('[data-s-type]').forEach(b=>b.onclick=()=>{d.remove();if(b.dataset.sType==='team'){S.team=b.dataset.sId;go('teams')}else if(b.dataset.sType==='player'){go('players');setTimeout(()=>playerProfile(b.dataset.sId),80)}else{S.replayId=b.dataset.sId;go('intel')}})},180)};d.onclick=e=>{if(e.target===d)d.remove()}}
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|SELECT|TEXTAREA/.test(document.activeElement?.tagName)){e.preventDefault();globalSearch()}if(e.key==='Escape')document.querySelector('.globalSearch')?.remove()});


function rgbBars(rows,title){let mx=Math.max(...rows.map(x=>num(x.v)),1);return `<div class="rgbChart"><div class="vizTop"><span>${esc(title)}</span><span>ATLAS MODEL</span></div><div class="rgbBars">${rows.map((x,i)=>`<div class="rgbRow"><b>${esc(x.k)}</b><i><em style="--w:${Math.max(2,num(x.v)/mx*100)}%;--i:${i}"></em></i><strong>${esc(x.v)}</strong></div>`).join('')}</div></div>`}
function forecastArc(p,label){let v=Math.max(0,Math.min(100,num(p)));return `<div class="forecastArc" style="--p:${v}"><div><b>${v.toFixed(1)}%</b><span>${esc(label)}</span></div></div>`}
function pctBar(a,b){let x=Math.max(0,Math.min(100,num(a))),y=Math.max(0,Math.min(100,num(b)));return `<div class="probBar"><i style="width:${x}%"></i><b style="width:${y}%"></b></div>`}
function projectionTracker(games){let key='atlas-prediction-tracker-v39',saved=JSON.parse(localStorage.getItem(key)||'{}');(games||[]).forEach(g=>{if(!saved[g.id])saved[g.id]={id:g.id,pick:g.pick,away:g.away,home:g.home,away_prob:g.away_prob,home_prob:g.home_prob,created:Date.now()}});(S.games||[]).forEach(g=>{let x=saved[g.id],st=String(g.state||'').toLowerCase();if(!x||!(g.completed||st==='post'||String(g.status||'').toLowerCase().startsWith('final')))return;let ts=g.teams||[],a=ts.find(t=>t.side==='away')||ts[0]||{},h=ts.find(t=>t.side==='home')||ts[1]||{};let as=Number(a.score),hs=Number(h.score);if(Number.isFinite(as)&&Number.isFinite(hs)&&as!==hs){x.result=as>hs?normAb(a.abbr):normAb(h.abbr);x.correct=x.pick===x.result;x.final_score=as+'-'+hs}});localStorage.setItem(key,JSON.stringify(saved));let vals=Object.values(saved);return `<div class="trackerPanel"><div class="vizTop"><span>PREDICTION TRACKER</span><span>LOCAL SNAPSHOTS</span></div><div class="trackerStats"><div><b>${vals.length}</b><span>FORECASTS SAVED</span></div><div><b>${vals.filter(x=>x.result).length}</b><span>RESOLVED</span></div><div><b>${vals.filter(x=>x.correct===true).length}</b><span>CORRECT</span></div></div><small>ATLAS freezes each game forecast in this browser when you open Forecasts. Results can be resolved after finals without rewriting the original pick.</small></div>`}
async function forecast(){await Promise.all([ensure('teams'),ensure('games')]);let d={teams:[],games:[],fantasy:[],mvp:[],formula:{}};try{d=await api('/api/projections',{timeout:15000})}catch{}let teams=d.teams||[],games=(d.games||[]).filter(g=>Number.isFinite(Number(g.away_prob))&&Number.isFinite(Number(g.home_prob))&&Math.abs((Number(g.away_prob)+Number(g.home_prob))-100)<0.2&&g.away&&g.home),fantasy=d.fantasy||[],mvp=d.mvp||[];shell(`<main class="page forecastPage">${techTitle('ATLAS GAME DAY FINAL','Projections with receipts.','Every forecast is labeled as an ATLAS model output and built from verified standings + the stored final-game archive.')}<div class="forecastHero"><div><span>MODEL</span><b>ATLAS//39</b><small>SCHEDULE-NEUTRAL SEASON BASELINE</small></div><div><span>CLUBS</span><b>${teams.length}</b><small>RANKED BY MODEL STRENGTH</small></div><div><span>GAME FORECASTS</span><b>${games.length}</b><small>CURRENT UPCOMING SLATE · AUTO REFRESH</small></div><div><span>FANTASY SAMPLE</span><b>${fantasy.length}</b><small>ARCHIVE-QUALIFIED PLAYERS</small></div></div><section>${techTitle('POWER PROJECTION','End-of-season board','Projected wins are a schedule-neutral ATLAS baseline, not a guarantee.')}<div class="projectionGrid"><div class="projectionTable">${teams.map((x,i)=>`<button data-fteam="${x.abbr}"><span class="rank">${i+1}</span><img src="${esc(x.logo||logo(x.abbr))}"><b>${esc(x.abbr)}</b><em>${esc(x.record)}</em><div class="strength"><i style="width:${x.strength}%"></i></div><strong>${x.strength}</strong><mark>${x.projected_wins} W</mark></button>`).join('')||'<div class="empty">Projection feed unavailable.</div>'}</div><div>${rgbBars(teams.slice(0,12).map(x=>({k:x.abbr,v:x.projected_wins})),'PROJECTED WINS · TOP 12')}</div></div></section><section>${techTitle('GAME FORECASTS','Current slate','Probability is relative ATLAS strength plus a small home-field adjustment.')}<div class="gameForecasts">${games.map(g=>`<article><div class="forecastTeams"><b>${g.away}</b><span>@</span><b>${g.home}</b></div><div class="probVisual">${forecastArc(g.away_prob,g.away)}${pctBar(g.away_prob,g.home_prob)}${forecastArc(g.home_prob,g.home)}</div><div class="probLabels"><span>${g.away_prob}%</span><strong>ATLAS: ${g.pick}</strong><span>${g.home_prob}%</span></div><small>${esc(g.status)} · MODEL CONFIDENCE ${g.confidence}</small></article>`).join('')||'<div class="empty">No upcoming games in the current slate.</div>'}</div>${projectionTracker(games)}</section><section>${techTitle('ATLAS MVP PROJECTION','Model ladder','Not an official award ranking. Stored production is blended with projected team strength.')}<div class="mvpGrid">${mvp.slice(0,10).map((x,i)=>`<article><span>#${i+1}</span><div><b>${esc(x.name)}</b><small>${esc(x.team)} · ${esc(x.position)} · ${x.games} STORED GAMES</small></div><strong>${x.mvp_score}</strong></article>`).join('')||'<div class="empty">MVP ladder needs stored player box-score production.</div>'}</div></section><section>${techTitle('FANTASY PROJECTIONS','Archive-powered PPR-like model','40% stored-season average + 60% latest-three stored-game average.')}<div class="fantasyBoard">${fantasy.slice(0,24).map((x,i)=>`<button data-fplayer="${esc(x.id||'')}"><span>${i+1}</span><b>${esc(x.name)}</b><small>${esc(x.team)} · ${esc(x.position)} · ${x.games}G</small><em>${x.recent3_fppg} L3</em><strong>${x.projected_fantasy}</strong></button>`).join('')||'<div class="empty">Fantasy projections appear as ATLAS captures final-game player stats.</div>'}</div></section><section>${techTitle('FORMULA LAB','How ATLAS reaches the number','No hidden sportsbook line and no fake Next Gen data.')}<div class="formulaGrid">${Object.entries(d.formula||{}).map(([k,v])=>`<article><span>${esc(k.replaceAll('_',' ').toUpperCase())}</span><p>${esc(v)}</p></article>`).join('')}</div></section>${provenance(d.source,d.updated,true)}</main>`);document.querySelectorAll('[data-fteam]').forEach(x=>x.onclick=()=>go('teams',{team:x.dataset.fteam}));document.querySelectorAll('[data-fplayer]').forEach(x=>x.onclick=()=>{let id=x.dataset.fplayer;if(id){go('players');setTimeout(()=>playerProfile(id),100)}})}
